[999999] = {999999, "幻光初爍", "4_199000_0,3_199001_1500,2_199002_8500", "0", "0", "1_110031_0", "1_110031_0", 0, 0, 0, 4, 10, 4, "0", 0, 10, 0, "700000", "0", "本卡池為新手卡池，只可通過精英調度券抽取駕駛員\nSSR駕駛員概率為<color=#ED6A47>100%</color>，必定可獲取1名SSR駕駛員", "1", "0", 0, "huanguangchushuo", 0, 1, "0", "huanguangchushuo_yeqian", "11001,12005,11002", "0", "0", 0, "Item/Rank/shijiandi2,ui_tongyong_text241", 0, "0", "0", "chouka_004", 0, "0", 0, "choujiang_putongqianyue", "choujiang_jingyingqianyue", "0", "0", "0"},
[999998] = {999998, "永世之盾", "4_190000_250,3_190001_1500,2_190002_8250", "0", "0", "1_110030_1", "1_110030_10", 65, 0, 328, 4, 10, 3, "0", 0, 0, 0, "700000", "0", "本卡池為常駐卡池，只可通過定向調度券抽取駕駛員\nSSR駕駛員的基礎概率為<color=#ED6A47>2.5%</color>，綜合概率（含保底）為<color=#ED6A47>3%</color>，最多<color=#ED6A47>95</color>次調度必定能通過保底獲取SSR駕駛員\n\n每次調度獲得<color=#ED6A47>1張</color>命運回饋券，累積獲得<color=#ED6A47>200張</color>命運回饋券可在本卡池範圍內隨機兌換一名SSR駕駛員\n<color=#ED6A47>注意：</color>命運回饋券可繼承保留", "0", "0", 1, "yongshizhidun", 999, 1, "0", "yongshizhidun_yeqian", "11001,13009,11023", "4_100015_1", "999999", 0, "0", 0, "0", "0", "chouka_005", 1, "0", 0, "choujiang_putongqianyue", "choujiang_jingyingqianyue", "0", "0", "0"},
[999997] = {999997, "自选调度", "4_190000_250,3_190001_1500,2_190002_8250", "0", "0", "1_110030_1", "1_110030_10", 65, 0, 328, 4, 10, 3, "0", 0, 0, 0, "700000", "0", "本卡池為月重置自選卡池，只可通過定向調度券抽取駕駛員\nSSR駕駛員的基礎概率為<color=#ED6A47>2.5%</color>，綜合概率（含保底）為<color=#ED6A47>3%</color>，最多<color=#ED6A47>95次</color>調度必定能通過保底獲取SSR駕駛員。其中自選的兩名SSR駕駛員和兩名SR駕駛員的概率提升，占總概率的<color=#ED6A47>50%</color>，即两名自選SSR駕駛員總概率為<color=#ED6A47>1.25%</color>。\n特殊保底机制：抽取出SSR駕駛員時，如果不是選定的SSR駕駛員，則第二次获得SSR駕駛員必定為選定的駕駛員之一，第三次抽取出SSR駕駛員時，必定為两名選定駕駛員中未抽取出的駕駛員，即前三次获得的SSR驾驶员中，必定获得全部SSR自选驾驶员。\n该卡池每月<color=#ED6A47>1号</color>重置，特殊保底机制每次重置仅能触发一次。卡池重置時將會重置累计的特殊保底次数，但并不会重置基础的保底次数。\n\n每次調度獲得<color=#ED6A47>1張</color>命運回饋券，累積獲得<color=#ED6A47>200張</color>命運回饋券可在本卡池範圍內隨機兌換一名SSR駕駛員\n<color=#ED6A47>注意：</color>命運回饋券可繼承保留", "1", "0", 1, "zixuandiaodu", 998, 5, "0", "zixuandiaodu_yeqian", "0", "4_100015_1", "999999", 0, "0", 4, "0", "0", "chouka_001", 1, "2_3;2_4", 0, "choujiang_putongqianyue", "choujiang_jingyingqianyue", "0", "0", "0"},
[999995] = {999995, "新人领航72小时限时调度", "4_199004_250,3_199005_1500,2_199006_8250", "0", "0", "1_110031_1", "1_110031_10", 75, 0, 490, 4, 10, 3, "0", 0, 0, 1, "700072", "0", "本卡池为新手限时卡池，只可通过精英调度券抽取驾驶员\nSSR驾驶员的基础概率为<color=#ED6A47>2.5%</color>，综合概率（含保底）为<color=#ED6A47>3%</color>。\n每次调度获得<color=#ED6A47>1张</color>新人回馈券，<color=#ED6A47>新人回馈券</color>可兑换本卡池范围内的限定SSR驾驶员、限定SR驾驶员\n<color=#ED6A47>注意：</color>新人回馈券可在往期商店中兑换成调度回馈券", "0", "0", 1, "72xiaoshixinren", 1, 1, "0", "72xiaoshixinren_yeqian", "10019,10020,10027,10029,10034,10036,10038,11027,11032,11039,11040,11042,11048,11050,12017,12018,12026,13011,12028,11051,11052,12029,13026,10043", "4_100021_1", "999998", 0, "Item/Rank/shijiandi,ui_tongyong_text240", 0, "0", "0", "chouka_001", 1, "0", 0, "choujiang_putongqianyue", "choujiang_jingyingqianyue", "0", "0", "0"},
[400003] = {400003, "骅骝启新程", "4_190000_250,3_190001_1500,2_190002_8250", "0", "0", "1_119004_10", "1_119004_10", 65, 0, 328, 4, 10, 3, "0", 0, 0, 1, "999998", "0", "本卡池為特殊卡池，只可通過「驊騮調度券」進行十連調度\nSSR駕駛員的基礎槪率為<color=#ED6A47>2.5%</color>，綜合槪率（含保底）為<color=#ED6A47>3%</color>，最多<color=#ED6A47>95</color>次調度必定能通過保底獲取SSR駕駛員\n特殊卡池無法獲取調度回饋券", "1", "0", 1, "suiyanlianxun", 2, 1, "0", "suiyanlianxun_yeqian", "11000,13001,10001", "0", "0", 0, "Item/Rank/shijiandi,ui_tongyong_text240", 0, "0", "0", "chouka_001", 0, "0", 0, "choujiang_putongqianyue", "choujiang_jingyingqianyue", "0", "0", "0"},
