[100001] = {100001, "夢星伊始", "4_190003_250,3_190004_1500,2_190005_8250", "0", "0", "1_110032_1", "1_110032_1", 0, 0, 0, 4, 10, 4, "0", 0, 10, 0, "700000", "0", "本卡池為常駐卡池，只可通過王牌調度券進行一次十連調度，必定可獲取1名SSR駕駛員（SSR駕駛員「辛西婭」占SSR駕駛員出現概率的<color=#ED6A47>33.33%</color>），每次調度可獲得<color=#ED6A47>1張</color>調度回饋券\n<color=#ED6A47>注意：</color>調度回饋券可繼承保留", "1", "0", 1, "mengxingyishi", 997, 1, "0", "mengxingyishi_yeqian", "10021", "4_100012_1", "9000", 0, "Item/Rank/shijiandi2,ui_tongyong_text241", 0, "0", "0", "chouka_001", 1, "0", 0, "choujiang_putongqianyue", "choujiang_jingyingqianyue", "0", "0", "0"},
[100200] = {100200, "限定卡池", "4_190308_250,3_190309_1500,2_190310_8250", "0", "0", "1_110031_1", "1_110031_10", 65, 0, 328, 4, 10, 3, "0", 0, 0, 1, "700001", "0", "本卡池為限時卡池，只可通過精英調度券抽取駕駛員\nSSR駕駛員的基礎概率為<color=#ED6A47>2.5%</color>，綜合概率（含保底）為<color=#ED6A47>3%</color>（當獲取SSR駕駛員時，有<color=#ED6A47>50%</color>概率為當期概率提升SSR駕駛員「莉莉絲·婚紗」；當在本卡池中<color=#ED6A47>首次</color>獲取的SSR駕駛員非當期概率提升 SSR駕駛員時，則下一次獲取的SSR駕駛員必定為當期概率提升SSR駕駛員），最多<color=#ED6A47>95</color>次調度必定能通過保底獲取SSR駕駛員\nSR駕駛員的出現概率為<color=#ED6A47>15%</color>，每進行一次<color=#ED6A47>十連調度</color>，必定能通過保底獲取SR或以上駕駛員\n本卡池保底無法繼承至其他卡池\n每次調度獲得<color=#ED6A47>1張</color>調度回饋券，累積獲得<color=#ED6A47>200張</color>調度回饋券可兌換SSR駕駛員「莉莉絲·婚紗」\n<color=#ED6A47>注意：</color>調度回饋券可繼承保留", "0", "0", 1, "xianshidiaodu", 102, 1, "0", "xianshidiaodu_yeqian", "12036", "4_100012_1", "9111", 0, "Item/Rank/shijiandi,ui_tongyong_text240", 4, "12036", "1_190311", "chouka_001", 1, "0", 0, "choujiang_putongqianyue", "choujiang_jingyingqianyue", "0", "0", "0"},
