[100202] = {100202, "阶梯卡池", "4_190308_250,3_190309_1500,2_190310_8250", "0", "0", "1_110031_10", "1_110031_10", 65, 0, 328, 4, 10, 3, "0", 0, 50, 1, "700001", "0", "本卡池為限時卡池，卡池共有<color=#ED6A47>五</color>個階段，共可進行<color=#ED6A47>五</color>次<color=#ED6A47>十連調度</color>。前<color=#ED6A47>三</color>次<color=#ED6A47>十連調度</color>將享受<color=#ED6A47>優惠折扣</color>，第<color=#ED6A47>四，五</color>次<color=#ED6A47>十連調度</color>將獲得額外獎勵。\nSSR駕駛員的基礎概率為<color=#ED6A47>2.5%</color>（當獲取SSR駕駛員時，有<color=#ED6A47>50%</color>概率為當期概率提升SSR駕駛員「莉莉絲·婚紗」；當在本卡池中<color=#ED6A47>首次</color>獲取的SSR駕駛員非當期概率提升 SSR駕駛員時，則下一次獲取的SSR駕駛員必定為當期概率提升SSR駕駛員）\nSR駕駛員的出現概率為<color=#ED6A47>15%</color>，每進行一次<color=#ED6A47>十連調度</color>，必定能通過保底獲取SR或以上駕駛員\n本卡池保底無法繼承至其他卡池\n每次調度可獲得<color=#ED6A47>1張</color>調度回饋券\n<color=#ED6A47>注意：</color>調度回饋券可繼承保留", "1", ";;1_312036_10;1_110140_1;1_110357_1", 1, "jieduandiaodu", 101, 3, "1,1_100008_500;2,1_100000_750;3,1_100008_1000;4,1_100000_1500;5,1_100008_2000", "jieduandiaodu_yeqian", "12036", "4_100012_1", "9111", 0, "Item/Rank/shijiandi3,ui_tongyong_text254", 4, "12036", "1_190311", "chouka_001", 1, "0", 0, "choujiang_putongqianyue", "choujiang_jingyingqianyue", "0", "0", "0"},
